    """Restore the recurring vertical stripe value in each column."""
    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]
    for c in range(w):
        observed = [grid[r][c] for r in range(h) if grid[r][c] != 0]
        if not observed:
            continue
        # Erasures occur in large blocks; the surviving cells in a column
        # identify its repeated color. Resolve ties by the earliest occurrence.
        counts = {value: observed.count(value) for value in set(observed)}
        value = max(counts, key=counts.get)
        for r in range(h):
            if grid[r][c] == 0:
                out[r][c] = value
    return out

